// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public {
        // Ensure the sender is the depositor account for the reference behavior
        vm.prank(0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001);
        try c.setL1BlockValues(
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        ) returns (bool ok) {
            // If the call succeeded, the timestamp must equal _timestamp
            assertEq(c.timestamp(), _timestamp);
        } catch {
            // In the reference version, the call should always succeed from the depositor.
            // In the buggy version, it will revert. We assert that if it reverted,
            // the timestamp remains 0 (its default), which differs from _timestamp
            // if _timestamp != 0, thus the bug is exposed.
            assertEq(c.timestamp(), 0);
        }
    }
}

contract InvMutTest {
    C public c;
    bool public didRevert;

    constructor(C _c) {
        c = _c;
    }

    function test(address caller, uint64 _number, uint64 _timestamp, uint256 _basefee, bytes32 _hash, uint64 _sequenceNumber, bytes32 _batcherHash, uint256 _l1FeeOverhead, uint256 _l1FeeScalar) external {
        require(caller != 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001);
        didRevert = true;
        (bool success, ) = address(c).call(abi.encodeWithSelector(C.setL1BlockValues.selector, _number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar));
        if (success) {
            didRevert = false;
        }
        assert(didRevert == true);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address sender, uint64 _number, uint64 _timestamp, uint256 _basefee, bytes32 _hash, uint64 _sequenceNumber, bytes32 _batcherHash, uint256 _l1FeeOverhead, uint256 _l1FeeScalar) public payable {
        require(sender != 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001);
        bool reverted;
        require(address(this).balance >= 0);
        try c.setL1BlockValues{from: sender}(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar) { reverted = false; } catch { reverted = true; }
        assert(reverted == true);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address sender) public {
        require(sender != 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001);
        bool reverted;
        try c.setL1BlockValues{from: sender}(0, 0, 0, bytes32(0), 0, bytes32(0), 0, 0) { reverted = false; } catch { reverted = true; }
        assert(reverted == true);
    }
    receive() external payable {}
}
